/**
 * 显示定点小数（支持任意整数/小数位数，统一 offset 高亮）
 * @param x, y: 起始坐标
 * @param integer: 整数部分（0~10^int_digits-1）
 * @param decimal: 小数部分（0~10^dec_digits-1）
 * @param int_digits: 整数位数（≥1，如1/2/3/4）
 * @param dec_digits: 小数位数（≥1，如1/2/3）
 * @param Size: 字体大小
 * @param offset: 高亮位索引（从左到右，仅数字位：0,1,2,...；0xFF=不亮）
 *                - 格式 000.0 → offset: 0(百),1(十),2(个),3(小1)
 *                - 格式 0000.00 → offset:0(千),1(百),2(十),3(个),4(小1),5(小2)
 * @param Is_Reverse: 1=反显高亮位，0=正常
 * @note 适配任意位数，替代原固定00.00格式；51单片机下int_digits建议≤4（u16最大65535）
 */
void LCD_DisplayFixedPoint(u8 x, u8 y, u16 integer, u16 decimal, 
                           u8 int_digits, u8 dec_digits, u8 Size, u8 offset, u8 Is_Reverse)
{
    // C89强制：所有变量声明放在函数开头
    u8 total_int_len = int_digits;    // 整数总位数（改为直接使用传入值，支持任意位数）
    u8 total_dec_len = dec_digits;    // 小数总位数（改为直接使用传入值，支持任意位数）
    u16 max_int = 1;                  // 整数部分最大值（如3位→999）
    u16 max_dec = 1;                  // 小数部分最大值（如2位→99）
    u8 digit_offset;
    u8 int_highlight = 0xFF;          // 整数部分高亮位（0xFF=无）
    u8 dot_x, dec_x;
    u8 dec_highlight = 0xFF;          // 小数部分高亮位（0xFF=无）
    u8 i;

    // ========== 1. 计算整数/小数部分的最大值（适配任意位数） ==========
    // 计算max_int = 10^int_digits - 1（如int_digits=3 → 999）
    for(i = 0; i < total_int_len; i++) {
        max_int *= 10;
    }
    max_int -= 1;
    // 计算max_dec = 10^dec_digits - 1（如dec_digits=1 → 9）
    for(i = 0; i < total_dec_len; i++) {
        max_dec *= 10;
    }
    max_dec -= 1;

    // ========== 2. 数值钳位（防止超出位数范围） ==========
    if (integer > max_int) integer = max_int;
    if (decimal > max_dec) decimal = max_dec;

    // ========== 3. 显示整数部分（支持任意位数） ==========
    // 匹配整数部分的高亮offset（0~total_int_len-1）
    for (digit_offset = 0; digit_offset < total_int_len; digit_offset++)
    {
        if (offset == digit_offset)
        {
            int_highlight = digit_offset; // 命中高亮位
            break;
        }
    }
    // 显示整数：传入实际位数、高亮位
    LCD_DisplayNum(x, y, integer, Size, total_int_len, int_highlight,
                   (int_highlight != 0xFF) ? Is_Reverse : 0, 1);

    // ========== 4. 显示小数点 ==========
    dot_x = x + total_int_len * 9;  // 9=单数字宽度（适配你的字体大小）
    LCD_DisplayString(dot_x, y, ".", Size, 0);

    // ========== 5. 显示小数部分（支持任意位数） ==========
    dec_x = dot_x + 3; // 小数点宽度（适配你的字体）
    // 小数部分的offset起始索引 = 整数位数（如3位整数→小数从3开始）
    for (digit_offset = 0; digit_offset < total_dec_len; digit_offset++)
    {
        if (offset == (total_int_len + digit_offset))
        {
            dec_highlight = digit_offset; // 小数部分内的相对偏移
            break;
        }
    }
    // 显示小数：传入实际位数、高亮位
    LCD_DisplayNum(dec_x, y, decimal, Size, total_dec_len, dec_highlight,
                   (dec_highlight != 0xFF) ? Is_Reverse : 0, 1);
}
//宽16列  ， row行数  画图
void LCD_DisplayBpm(unsigned int x, unsigned char y, unsigned char rows,char* ch) {

    unsigned char col_lsb, col_msb;

    unsigned char row, col;
    x=x/3;
    // 计算列地址
    col_lsb = 0x00 | (x & 0x0F);      // 列地址低4位
    col_msb = 0x10 | ((x & 0xF0) >> 4); // 列地址高4位
    for (row = 0; row < rows; row++) {
        // 设置RAM地址
		LCD_WriteCmd(0x89);  // 进入RAM地址控制模式
		LCD_WriteCmd(col_lsb);
		LCD_WriteCmd(col_msb);
		LCD_WriteCmd(0x60 | ((y + row) & 0x0F));
		LCD_WriteCmd(0x70 | (((y + row) & 0xF0) >> 4));


		for (col = 0; col < 9; col++) {

				LCD_WriteData(*ch++);
		}
   
    LCD_WriteCmd(0x88);  // 退出RAM地址控制模式
}
}

//  画水平线  x起始  x1  结束
void LCD_DisplayLine(unsigned char x, unsigned char y,unsigned char x1,uint8_t type) {
	
	  unsigned char col_lsb, col_msb;

    unsigned char row, col;
    	  row=(x1-x)/2;
	x=x/3;
    // 计算列地址
    col_lsb = 0x00 | (x & 0x0F);      // 列地址低4位
    col_msb = 0x10 | ((x & 0xF0) >> 4); // 列地址高4位
		LCD_WriteCmd(0xf4);			//(30) 起始列
		LCD_WriteCmd(0x00);			//start from 0
		LCD_WriteCmd(0xf6);			//(32) 结束列
		LCD_WriteCmd(0x4f);			//end:240

		LCD_WriteCmd(0xf5);			//(31) 起始行
		LCD_WriteCmd(0x00);			// 0
		LCD_WriteCmd(0xf7);			//(32) 结束行
		LCD_WriteCmd(0x7F);			// 128

		LCD_WriteCmd(0x89);			//(12) 启用自动增量，在扫描方向上自动增量1
    // 设置整个屏幕的起始地址
    LCD_WriteCmd(0x60);  // 起始行 LSB
    LCD_WriteCmd(0x70);  // 起始行 MSB  
    LCD_WriteCmd(0x00);  // 起始列 LSB
    LCD_WriteCmd(0x10);  // 起始列 MSB

        // 设置RAM地址
		LCD_WriteCmd(0x89);  // 进入RAM地址控制模式
		LCD_WriteCmd(col_lsb);
		LCD_WriteCmd(col_msb);
		LCD_WriteCmd(0x60 | ((y) & 0x0F));
		LCD_WriteCmd(0x70 | (((y) & 0xF0) >> 4));


		for (col = 0; col < row; col++) {

				LCD_WriteData(0xff);
		}
		if(type)
		{
   				LCD_WriteData(0xf0);				LCD_WriteData(0x00);
		}
    LCD_WriteCmd(0x88);  // 退出RAM地址控制模式

		
}	



